ROOT = Path(__file__).resolve().parents[1]
DOCS, DASH = ROOT / "docs", ROOT / "docs" / "dashboard"
MODEL = ROOT / "BlinkitSales-PBI.SemanticModel" / "definition"
PDF = DOCS / "BlinkitSales-PBI_Project_Guide.pdf"
HTML = DOCS / "guide" / "project_guide.html"
FACTS = json.loads((ROOT / "data" / "clean" / "report_facts.json").read_text(encoding="utf-8"))

TH = g.Theme(navy="#0A3D1F", primary="#0C831F", secondary="#0F5A2B", accent="#B98300", bad="#C0392B", good="#1E7F4B",
             ink="#13241A", muted="#4A5750", bg="#F5F7F1", line="#DCE3D8", row_alt="#F1F6EC", subtitle="#CFE8D4",
             tint="#E6F3E8", cover_end="#0F5A2B")

measures = g.parse_measures(MODEL)
n_meas = len(measures)
commits = g.git_commits(ROOT)
L = lambda v: f"₹{v / 1e5:,.2f} L"


def dax(name, maxlen=900):
    row = measures[measures.name == name]
    return f"{name} =\n{row.iloc[0].expr[:maxlen]}" if len(row) else f"-- {name}: see _Measures.tmdl"


def img(path, cls="full", style=""):
    return f'<img class="{cls}" src="{uri(path)}" style="{style}">'


def rows(*items, columns):
    return table(pd.DataFrame(list(items), columns=columns))


sections = []

