# ------------------------------------------------------------------ 13 lessons
lessons = [
    "<b>Reconcile before you chart.</b> Two independent calculations of 70 values meant every later mismatch was a build bug.",
    "<b>Let the audit set the definitions.</b> Order total vs item lines forced a revenue rule and a separate \"line value\" label before any visual existed.",
    "<b>Say the data is synthetic.</b> Flat distributions and a zero delay-rating link are findings in themselves; the report states them.",
    "<b>Generate the model and report from code.</b> Fixes go into the generator and the whole thing rebuilds; no hand edits to drift.",
    "<b>Calibrate the layout checker early.</b> Three rounds were lost to clipping and overflow a stricter preflight would have caught before the export.",
    "<b>Refresh is part of the build.</b> A stale Desktop cache made fixed items look unfixed; delete cache.abf with Desktop closed.",
    "<b>Honest forecasts.</b> The simplest model won the backtest; the report shows the backtest, the band and the caveat.",
    "<b>Keep personal data out of git from the first commit</b>, and keep the handoff note out of the repo.",
]
sections.append(section(14, "Lessons learned", "What carries over to the next project.", "<ol class='lessons'>" + "".join(f"<li>{x}</li>" for x in lessons) + "</ol>"))

